public Map<String, String> getStyleResources() {
  if (styleResources != null) {
    return styleResources;
  }
  try {
    ResourceBundle resourceBundle = ResourceBundle.getBundle(DEFAULT_STYLE_RESOURCE_PATH);
    Map<String, String> resources = new TreeMap<String, String>();
    this.initResources(resourceBundle, resources);
    this.initStylePluginResources(resources);
    styleResources = resources;
    return resources;
  } catch (MissingResourceException | ClassCastException | UnsupportedOperationException | IllegalArgumentException | IndexOutOfBoundsException | NullPointerException e) {
    // Handle the exception as needed, e.g., logging, rethrow, or a fallback return
    System.err.println("An error occurred while initializing style resources: " + e.getMessage());
    return null; // or an empty map, or another appropriate action
  }
}
